import{z as o,x as A,o as r,c as d,q as l,j as n,D as E,d as t,s as B,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"波动率微笑插值","description":"","frontmatter":{"title":"波动率微笑插值","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/smile-interpolation.md","filePath":"quant/smile-interpolation.md","lastUpdated":1791413859000}'),p={name:"quant/smile-interpolation.md"};function m(u,a,D,h,C,g){const i=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="波动率微笑插值" tabindex="-1">波动率微笑插值 <a class="header-anchor" href="#波动率微笑插值" aria-label="Permalink to &quot;波动率微笑插值&quot;">​</a></h1><div class="epigraph"><p>交易所只在挂牌行权价上报价，组合与对冲要的是整条曲线——插值不是发明数据，是在两个已知点之间画一条「贵得最合理」的桥。</p><footer>—— 据 Gatheral, The Volatility Surface, 2006；Breeden and Litzenberger, 1978</footer></div><p><a href="/quant/yang-zhang">上一课</a>把已实现波动的测量做完，本课转到隐含一侧：同一到期日的期权只在十几个挂牌行权价上有盘口，而给奇异期权定价、按 vega 分桶、算边际希腊字母都需要一条连续的 smile。缺口是插值方式本身——随手线性插值会造出负曲率的曲线，而曲率是风险中性密度的符号，负了就是套利。本课写流程与判废标准，不展开 SVI 全套校准与曲面动力学（<a href="/quant/vol-surface">波动率曲面</a>）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个缺口。其一，行权价离散：报价之间与翼部之外都是空档，临近到期时挂牌 strikes 变稀，外推段的占比反而更大。其二，插值变量选错：直接对隐含波动率 \\(\\sigma(K)\\) 做三次样条，二阶导不受约束，曲率符号失控。本课不写时间维度的曲面拼接，也不写贴现与红利的预处理，只管单一到期日、清洗报价之后的 strike 方向插值。</p><p><span class="marginnote">术语翻译：微笑（smile）是同一到期日下隐含波动率对行权价的 U 形截面；偏斜（skew）指左翼抬高的不对称；翼部（wing）是深价内与深价外两端。业界的「vol 曲线」多指这条一维截面，不是整张曲面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准流程五步：清洗（剔除宽摆与陈旧报价）、变量转换（\\(\\sigma(K)\\) 换成总方差 \\(w(k)=\\sigma^2(k)T\\)，\\(k=\\ln(K/F)\\) 是对数远期行权价）、加权（按 vega 或买卖点差）、插值（保形分段三次 Hermite 优于自然样条）、翼部处理（用幂律或线性斜率封顶，不许样条自由飞）。<span class="marginnote">数字实例：某股指 3 个月期权的挂牌 strikes 从 \\(k=-0.25\\) 到 \\(0.15\\) 共 13 档，实盘组合却压着 \\(k=-0.40\\) 的深度价外看跌——外推段贡献的 vega 占组合三成，翼部怎么封顶直接改变对冲手数。</span></p>',8)),(r(),n(s,null,{default:E(()=>[B(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8F%96%E5%90%8C%E5%88%B0%E6%9C%9F%E6%97%A5%E5%85%A8%E9%83%A8%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20CLEAN%5B%22%E5%89%94%E9%99%A4%E5%AE%BD%E6%91%86%E4%B8%8E%E9%99%88%E6%97%A7%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20CLEAN%20--%3E%20CONV%5B%22%E6%8D%A2%E6%88%90%E5%AF%B9%E6%95%B0%E8%A1%8C%E6%9D%83%E4%BB%B7%E4%B8%8E%E6%80%BB%E6%96%B9%E5%B7%AE%22%5D%0A%20%20CONV%20--%3E%20WGT%5B%22%E6%8C%89%20vega%20%E6%88%96%E7%82%B9%E5%B7%AE%E5%8A%A0%E6%9D%83%22%5D%0A%20%20WGT%20--%3E%20FIT%5B%22%E4%BF%9D%E5%BD%A2%E6%8F%92%E5%80%BC%E5%87%BA%20w(k)%22%5D%0A%20%20FIT%20--%3E%20WING%5B%22%E7%BF%BC%E9%83%A8%E5%B0%81%E6%96%9C%E7%8E%87%E5%B9%B6%E5%A4%96%E6%8E%A8%22%5D%0A%20%20WING%20--%3E%20CHK%5B%22%E6%9B%B2%E7%8E%87%E7%AC%A6%E5%8F%B7%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[t("Breeden–Litzenberger 给出判废标准：看涨期权对行权价的二阶导是风险中性密度，\\(\\rho(K)=e^{rT}\\,\\partial^2 C/\\partial K^2\\)，而 \\(\\partial^2 C/\\partial K^2\\gt 0\\) 等价于看涨价格曲线对行权价凸，这也是 smile 不能剧烈向下弯的根源——所以「曲线向下弯」不是审美问题，是 \\(\\rho\\) 出现负质量，衍生品定价从此可以被套利。保形插值的价值在于把二阶导约束写进算法：Hermite 分段在节点间保持形状，自然样条为最小化曲率能量常在翼部反翘。验收前置总比事后修补便宜。"),e("span",{class:"marginnote"},"直觉类比：插值像在两个已探明的桥墩之间架桥——两端标高是行情给的，桥型（直梁还是拱）由荷载检验（无套利）说了算，不是画得越顺眼越好。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：直接对 \\(\\sigma(K)\\) 样条然后喂进定价公式。错在哪一步？曲率检查本应做在价格或总方差上；对波动率本身插值再复合进 Black 公式，二阶导约束被指数复合破坏，负密度从后门溜进来。")],-1)),(r(),n(s,null,{default:E(()=>[B(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%E6%8B%9F%E5%90%88%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20Q1%7B%22%E6%9B%B2%E7%8E%87%E9%9D%9E%E8%B4%9F%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E8%BF%9D%E5%8F%8D%22%7C%20REJ%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%E5%AF%86%E5%BA%A6%E6%9C%89%E8%B4%9F%E8%B4%A8%E9%87%8F%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%BB%A1%E8%B6%B3%22%7C%20Q2%7B%22%E6%80%BB%E6%96%B9%E5%B7%AE%E9%9A%8F%E5%88%B0%E6%9C%9F%E6%97%A5%E5%8D%95%E8%B0%83%E5%A2%9E%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E8%BF%9D%E5%8F%8D%22%7C%20REJ2%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E6%97%A5%E5%8E%86%E5%A5%97%E5%88%A9%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%BB%A1%E8%B6%B3%22%7C%20ACC%5B%22%E6%8E%A5%E5%8F%97%E5%B9%B6%E8%BE%93%E5%87%BA%E5%B8%8C%E8%85%8A%E5%AD%97%E6%AF%8D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>插值只管一维截面，跨到期日的日历约束要放到曲面上一起管。翼部本质是观点不是数据：流动性到 \\(k=-0.25\\) 为止，再往外的一切斜率都来自外推假设，压尾还是抬尾会显著改变尾部 vega。与 SVI 校准的分工：参数化把无套利写进参数空间，插值把无套利当验收条件——strike 密度够、曲面稳定时插值够用，跨期限联动复杂时上参数化。校准翻车时先分清是插值段出了负曲率还是报价坏档，别急着全盘重估。曲率一侧连着 <a href="/quant/vol-surface">波动率曲面</a> 的日历一致性，一侧连着 <a href="/quant/risk-budgeting">风险预算</a> 里对尾部 vega 的限额。</p><p><span class="marginnote">数字实例：同一组报价，线性插值与保形样条给出的 25-delta 风险逆转可差 0.3 个波动率点；对持有上万张期权的做市商，一个波动率点约等于数十万美元的逐日盯市差异——插值器是隐形的头寸。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>插值五步：清洗、换总方差、加权、保形插值、翼部封斜率。</li><li>判废标准是 Breeden–Litzenberger 密度非负，即看涨价格对行权价凸。</li><li>对 \\(\\sigma\\) 直接样条是经典翻车点：二阶导约束被复合破坏。</li><li>翼部是外推假设，责任在建模者不在数据。</li><li>出处：Breeden and Litzenberger, <em>Journal of Business</em>, 1978；Gatheral, <em>The Volatility Surface</em>, 2006；SVI 参数化见 Gatheral and Jacquier, 2014。</li></ul>',5))])}const F=o(p,[["render",m]]);export{c as __pageData,F as default};
